#include <stdio.h>

int main() {
    int A[2][3];
    int B[3][2];
    int C[2][2];

    A[0][0] = 1;
    A[0][1] = 2;
    A[0][2] = 3;
    A[1][0] = 4;
    A[1][1] = 5;
    A[1][2] = 6;

    B[0][0] = 7;
    B[0][1] = 8;
    B[1][0] = 9;
    B[1][1] = 1;
    B[2][0] = 2;
    B[2][1] = 3;

    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            C[i][j] = 0;
            for (int k = 0; k < 3; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    printf("C = [[%d, %d], [%d, %d]]\n", C[0][0], C[0][1], C[1][0], C[1][1]);

    if (C[0][0] == 31 && C[0][1] == 19 && C[1][0] == 85 && C[1][1] == 55) {
        return 42;
    }
    return 1;
}
